import React from 'react'
import Col from 'react-bootstrap/Col';
import Container from 'react-bootstrap/Container';
import Image from 'react-bootstrap/Image';
import Row from 'react-bootstrap/Row';
import Logo from '../../assets/images/Logo.png'

const Home = () => {
  return (
    <Container>
      <Row>
        <Col xs={6} md={4}>
          <Image src={Logo} rounded className='w-75' />
        </Col>
        <h1 className='text-center mt-5'>Welcome to Event Manager</h1>
        <p className='text-center mt-3'>Your one-stop solution for managing your events and tasks efficiently. Stay organized and never miss a deadline with our intuitive event management platform.</p>
      </Row>
    </Container>
  )
}

export default Home
